<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$id=filter_var($_POST['room_id']??null,FILTER_VALIDATE_INT);$name=trim((string)($_POST['room_name']??''));$house=trim((string)($_POST['boarding_house']??''));$gender=(string)($_POST['gender']??'');$capacity=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT);$parentRaw=trim((string)($_POST['house_parent_id']??''));$parent=$parentRaw===''?null:filter_var($parentRaw,FILTER_VALIDATE_INT);$active=isset($_POST['active'])?(int)$_POST['active']:1;
if($id===false||$parent===false||$name===''||strlen($name)>120||strlen($house)>100||!in_array($gender,['Boys','Girls','Mixed'],true)||!$capacity||$capacity>2000||!in_array($active,[0,1],true)){$_SESSION['error']='Enter a room name, valid room type, capacity and optional house parent.';header('Location: ../?page=boarding');exit;}
$pdo=db();try{$pdo->beginTransaction();if($parent){$q=$pdo->prepare("SELECT id FROM users WHERE id=:id AND active=1 AND role IN ('Administrator','Head','Teacher','Clerk') FOR UPDATE");$q->execute(['id'=>$parent]);if(!$q->fetch())throw new DomainException('Choose an active teacher, head or clerk as house parent.');}if($id){$q=$pdo->prepare('SELECT id FROM boarding_rooms WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);if(!$q->fetch())throw new DomainException('Boarding room not found.');$q=$pdo->prepare("SELECT COUNT(*) FROM boarding_allocations a JOIN students s ON s.id=a.student_id WHERE a.room_id=:room AND a.status='Active' AND (a.end_on IS NULL OR a.end_on>=CURDATE()) AND ((:gender='Boys' AND s.sex='F') OR (:gender2='Girls' AND s.sex='M'))");$q->execute(['room'=>$id,'gender'=>$gender,'gender2'=>$gender]);if((int)$q->fetchColumn())throw new DomainException('This room type conflicts with existing learner allocations.');$q=$pdo->prepare("SELECT COUNT(*) FROM boarding_allocations WHERE room_id=:room AND status='Active' AND (end_on IS NULL OR end_on>=CURDATE())");$q->execute(['room'=>$id]);if((int)$q->fetchColumn()>(int)$capacity)throw new DomainException('Capacity cannot be reduced below active and scheduled allocations.');$q=$pdo->prepare('UPDATE boarding_rooms SET room_name=:name,boarding_house=:house,gender=:gender,capacity=:capacity,house_parent_id=:parent,active=:active WHERE id=:id');$q->execute(['name'=>$name,'house'=>$house?:null,'gender'=>$gender,'capacity'=>$capacity,'parent'=>$parent?:null,'active'=>$active,'id'=>$id]);audit_log('boarding.room_updated','boarding_rooms',(int)$id,['capacity'=>$capacity,'gender'=>$gender,'active'=>$active]);}else{$q=$pdo->prepare('INSERT INTO boarding_rooms(room_name,boarding_house,gender,capacity,house_parent_id,active,created_by) VALUES(:name,:house,:gender,:capacity,:parent,:active,:user)');$q->execute(['name'=>$name,'house'=>$house?:null,'gender'=>$gender,'capacity'=>$capacity,'parent'=>$parent?:null,'active'=>$active,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('boarding.room_created','boarding_rooms',$id,['capacity'=>$capacity,'gender'=>$gender]);}$pdo->commit();$_SESSION['notice']='Boarding room saved.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Boarding room save failed: '.$e->getMessage());$_SESSION['error']=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&$e->getCode()==='23000'?'That room name is already in use.':'Could not save the boarding room.');}
header('Location: ../?page=boarding');exit;
